    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 3.2.1",
        "category": "Protect Stored Account Data",
        "title": "Account data storage is kept to a minimum through implementation of data retention and disposal policies, procedures, and processes that include at least the following: coverage for all locations of stored account data, coverage for any sensitive authentication data (SAD) stored prior to completion of authorization, limiting data storage amount and retention time to that which is required for legal or regulatory, and/or business requirements, specific retention requirements for stored account data that defines length of retention period and includes a documented business justification, processes for secure deletion or rendering account data unrecoverable when no longer needed per the retention policy, a process for verifying, at least once every three months, that stored account data exceeding the defined retention period has been securely deleted or rendered unrecoverable",
        "owner": "Shared",
        "additionalContentUrl": "",
        "metadata": {}
      },
      "id": "/providers/Microsoft.PolicyInsights/policyMetadata/PCI_DSS_v4.0.1_3.2.1",
      "name": "PCI_DSS_v4.0.1_3.2.1",
      "type": "Microsoft.PolicyInsights/policyMetadata"
    },
    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 3.3.2",
        "category": "Protect Stored Account Data",
        "title": "SAD that is stored electronically prior to completion of authorization is encrypted using strong cryptography",
