      "name": "PCI_DSS_v4.0.1_3.5.1.2",
      "type": "Microsoft.PolicyInsights/policyMetadata"
    },
    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 3.6.1.1",
        "category": "Protect Stored Account Data",
        "title": "Additional requirement for service providers only: A documented description of the cryptographic architecture is maintained that includes: details of all algorithms, protocols, and keys used for the protection of stored account data, including key strength and expiry date. Preventing the use of the same cryptographic keys in production and test environments. Description of the key usage for each key. Inventory of any hardware security modules (HSMs), key management systems (KMS), and other secure cryptographic devices (SCDs) used for key management, including type and location of devices, to support meeting Requirement 12.3.4",
        "owner": "Shared",
        "additionalContentUrl": "",
        "metadata": {}
      },
      "id": "/providers/Microsoft.PolicyInsights/policyMetadata/PCI_DSS_v4.0.1_3.6.1.1",
