    },
    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 3.6.1.2",
        "category": "Protect Stored Account Data",
        "title": "Secret and private keys used to protect stored account data are stored in one (or more) of the following forms at all times: encrypted with a key-encrypting key that is at least as strong as the data-encrypting key, and that is stored separately from the data-encrypting key. Within a secure cryptographic device (SCD), such as a hardware security module (HSM) or PTS-approved point-of-interaction device. As at least two full-length key components or key shares, in accordance with an industry-accepted method",
        "owner": "Shared",
        "additionalContentUrl": "",
        "metadata": {}
      },
