    },
    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 3.6.1",
        "category": "Protect Stored Account Data",
        "title": "Procedures are defined and implemented to protect cryptographic keys used to protect stored account data against disclosure and misuse that include: access to keys is restricted to the fewest number of custodians necessary. Key-encrypting keys are at least as strong as the data-encrypting keys they protect. Key-encrypting keys are stored separately from data-encrypting keys. Keys are stored securely in the fewest possible locations and forms",
        "owner": "Shared",
        "additionalContentUrl": "",
        "metadata": {}
      },
