    },
    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 3.7.3",
        "category": "Protect Stored Account Data",
        "title": "Key-management policies and procedures are implemented to include secure storage of cryptographic keys used to protect stored account data",
        "owner": "Shared",
        "additionalContentUrl": "",
        "metadata": {}
      },
      "id": "/providers/Microsoft.PolicyInsights/policyMetadata/PCI_DSS_v4.0.1_3.7.3",
      "name": "PCI_DSS_v4.0.1_3.7.3",
      "type": "Microsoft.PolicyInsights/policyMetadata"
    },
    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 3.7.5",
        "category": "Protect Stored Account Data",
        "title": "Key management policies procedures are implemented to include the retirement, replacement, or destruction of keys used to protect stored account data, as deemed necessary when: the key has reached the end of its defined cryptoperiod. The integrity of the key has been weakened, including when personnel with knowledge of a cleartext key component leaves the company, or the role for which the key component was known. The key is suspected of or known to be compromised. Retired or replaced keys are not used for encryption operations",
        "owner": "Shared",
        "additionalContentUrl": "",
        "metadata": {}
      },
