    },
    {
      "properties": {
        "metadataId": "PCI DSS v4.0.1 4.2.1",
        "category": "Protect Cardholder Data with Strong Cryptography During Transmission Over Open, Public Networks",
        "title": "Strong cryptography and security protocols are implemented as follows to safeguard PAN during transmission over open, public networks: Only trusted keys and certificates are accepted. Certificates used to safeguard PAN during transmission over open, public networks are confirmed as valid and are not expired or revoked. The protocol in use supports only secure versions or configurations and does not support fallback to, or use of insecure versions, algorithms, key sizes, or implementations. The encryption strength is appropriate for the encryption methodology in use",
        "owner": "Shared",
        "additionalContentUrl": "",
        "metadata": {}
      },
